"use client";

import { useState, useEffect } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import { AlertCircle, Loader2, Plus, Package, RefreshCw, Eye, Download, Info, X } from 'lucide-react';
import Layout from "../../Layout";

export default function ManageBons() {
  const navigate = useNavigate();
  const [bons, setBons] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState("");
  const [selectedSupplier, setSelectedSupplier] = useState("");
  const [selectedDay, setSelectedDay] = useState("");
  const [selectedMonth, setSelectedMonth] = useState("");
  const [selectedYear, setSelectedYear] = useState("");
  const [suppliers, setSuppliers] = useState([]);
  const [selectedSupplierInfo, setSelectedSupplierInfo] = useState(null);

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    setIsLoading(true);
    setError("");
    const token = localStorage.getItem("token");

    try {
      const [productsRes, suppliersRes] = await Promise.all([
        axios.get(`${process.env.REACT_APP_API_URL}/api/products`, { headers: { Authorization: `Bearer ${token}` } }),
        axios.get(`${process.env.REACT_APP_API_URL}/api/suppliers`, { headers: { Authorization: `Bearer ${token}` } }),
      ]);
      const allBons = productsRes.data
        .filter(product => product.bons && product.bons.length > 0)
        .flatMap(product => 
          product.bons.map((bon, index) => ({
            ...bon,
            productName: product.nameProduct,
            supplierName: product.nameSupplier[index] || "N/A",
          }))
        );
      setBons(allBons);
      setSuppliers(suppliersRes.data);
    } catch (err) {
      setError(err.response?.data?.message || "Erreur lors de la récupération des données");
    } finally {
      setIsLoading(false);
    }
  };

  const filteredBons = bons
    .filter((bon) =>
      selectedSupplier ? bon.supplierName === `${selectedSupplier.firstName} ${selectedSupplier.lastName}` : true
    )
    .filter((bon) => {
      const bonDate = new Date(bon.DateBon);
      return (
        (!selectedDay || bonDate.getDate().toString() === selectedDay) &&
        (!selectedMonth || (bonDate.getMonth() + 1).toString() === selectedMonth) &&
        (!selectedYear || bonDate.getFullYear().toString() === selectedYear)
      );
    });

  const days = Array.from({ length: 31 }, (_, i) => i + 1);
  const months = Array.from({ length: 12 }, (_, i) => i + 1);
  const years = Array.from(
    new Set(bons.map(bon => new Date(bon.DateBon).getFullYear()))
  ).sort();

  const handleShowBon = (bonPath) => {
    window.open(`${process.env.REACT_APP_API_URL}${bonPath}`, "_blank");
  };

  const handleDownloadBon = async (bonPath) => {
    const token = localStorage.getItem("token");
    const fullUrl = `${process.env.REACT_APP_API_URL}${bonPath}`;
    const fileName = bonPath.split("/").pop();

    try {
      const response = await axios.get(fullUrl, {
        headers: { Authorization: `Bearer ${token}` },
        responseType: "blob",
      });

      const blob = new Blob([response.data], { type: response.headers["content-type"] });
      const url = window.URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.download = fileName;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      window.URL.revokeObjectURL(url);
    } catch (err) {
      console.error("Erreur de téléchargement:", err.response || err);
      setError("Erreur lors du téléchargement du bon. Vérifiez la console pour plus de détails.");
    }
  };

  const handleShowSupplierInfo = (supplierName) => {
    const supplier = suppliers.find(s => `${s.firstName} ${s.lastName}` === supplierName);
    setSelectedSupplierInfo(supplier || { firstName: "N/A", lastName: "", email: "N/A", phoneNumber: "N/A" });
  };

  const closeSupplierModal = () => {
    setSelectedSupplierInfo(null);
  };

  return (
    <Layout>
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="bg-white rounded-2xl shadow-xl overflow-hidden border border-[#C8A45D/30]/50">
          <div className="bg-gradient-to-r from-[#00717F] to-[#C8A45D] text-white p-6">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
              <div>
                <h1 className="text-2xl font-bold tracking-tight">Gestion des Bons</h1>
                <p className="text-white/80 mt-1 text-sm">Liste des bons de livraison</p>
              </div>
              <div className="flex gap-4">
                <button
                  onClick={() => navigate("/Delivery")}
                  className="px-4 py-2.5 bg-white text-[#00717F] rounded-lg shadow-sm hover:bg-[#C8A45D/20] transition-colors duration-200 flex items-center gap-2 font-medium"
                >
                  <Package className="h-4 w-4" /> Livraison
                </button>
                <button
                  onClick={fetchData}
                  className="px-4 py-2.5 bg-white text-[#00717F] rounded-lg shadow-sm hover:bg-[#C8A45D/20] transition-colors duration-200 flex items-center gap-2 font-medium"
                >
                  <RefreshCw className="h-4 w-4" /> Rafraîchir
                </button>
              </div>
            </div>
          </div>

          {error && (
            <div className="mx-6 my-4 p-4 bg-red-50 border-l-4 border-red-500 rounded-r-lg flex items-center gap-3">
              <AlertCircle className="h-5 w-5 text-red-500 flex-shrink-0" />
              <p className="text-red-700 text-sm">{error}</p>
            </div>
          )}

          <div className="p-6 border-b border-[#C8A45D/30]/50">
            <h2 className="text-xl font-semibold text-[#00717F] mb-4">Recherche</h2>
            <div className="flex flex-col sm:flex-row gap-4">
              <select
                value={selectedSupplier ? `${selectedSupplier.firstName} ${selectedSupplier.lastName}` : ""}
                onChange={(e) => setSelectedSupplier(e.target.value ? suppliers.find(s => `${s.firstName} ${s.lastName}` === e.target.value) : "")}
                className="px-4 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-[#00717F] focus:border-transparent w-full sm:w-1/4"
              >
                <option value="">Tous les fournisseurs</option>
                {suppliers.map((supplier) => (
                  <option key={supplier._id} value={`${supplier.firstName} ${supplier.lastName}`}>
                    {supplier.firstName} {supplier.lastName}
                  </option>
                ))}
              </select>
              <select
                value={selectedDay}
                onChange={(e) => setSelectedDay(e.target.value)}
                className="px-4 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-[#00717F] focus:border-transparent w-full sm:w-1/4"
              >
                <option value="">Tous les jours</option>
                {days.map((day) => (
                  <option key={day} value={day}>
                    {day}
                  </option>
                ))}
              </select>
              <select
                value={selectedMonth}
                onChange={(e) => setSelectedMonth(e.target.value)}
                className="px-4 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-[#00717F] focus:border-transparent w-full sm:w-1/4"
              >
                <option value="">Tous les mois</option>
                {months.map((month) => (
                  <option key={month} value={month}>
                    {new Date(0, month - 1).toLocaleString('fr-FR', { month: 'long' })}
                  </option>
                ))}
              </select>
              <select
                value={selectedYear}
                onChange={(e) => setSelectedYear(e.target.value)}
                className="px-4 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-[#00717F] focus:border-transparent w-full sm:w-1/4"
              >
                <option value="">Toutes les années</option>
                {years.map((year) => (
                  <option key={year} value={year}>
                    {year}
                  </option>
                ))}
              </select>
            </div>
          </div>

          {isLoading ? (
            <div className="flex justify-center items-center h-64">
              <div className="flex flex-col items-center gap-2">
                <Loader2 className="h-10 w-10 text-[#00717F] animate-spin" />
                <p className="text-[#00717F] text-sm font-medium">Chargement des bons...</p>
              </div>
            </div>
          ) : (
            <div className="overflow-x-auto px-4 pb-6">
              <table className="min-w-full divide-y divide-[#C8A45D/30]">
                <thead>
                  <tr className="bg-[#F5F6FA] text-[#00717F]">
                    <th className="p-2 text-left text-xs font-semibold uppercase tracking-wider rounded-tl-lg">Fournisseur</th>
                    <th className="p-2 text-left text-xs font-semibold uppercase tracking-wider">Date du Bon</th>
                    <th className="p-2 text-left text-xs font-semibold uppercase tracking-wider">Type de Bon</th>
                    <th className="p-2 text-left text-xs font-semibold uppercase tracking-wider rounded-tr-lg">Bon de Livraison</th>
                  </tr>
                </thead>
                <tbody className="bg-white divide-y divide-[#C8A45D/30]/30">
                  {filteredBons.length === 0 ? (
                    <tr>
                      <td colSpan={4} className="py-8 text-center text-gray-500">
                        <Package className="h-12 w-12 mx-auto mb-2 text-gray-400" />
                        Aucun bon trouvé
                      </td>
                    </tr>
                  ) : (
                    filteredBons.map((bon) => (
                      <tr key={bon._id} className="hover:bg-[#F5F6FA]/30 transition-colors duration-150">
                        <td className="p-2 text-sm text-#333333">
                          <button
                            onClick={() => handleShowSupplierInfo(bon.supplierName)}
                            className="text-blue-600 hover:underline"
                          >
                            {bon.supplierName}
                          </button>
                        </td>
                        <td className="p-2 text-sm text-#333333">
                          {bon.DateBon ? new Date(bon.DateBon).toLocaleDateString('fr-FR') : "N/A"}
                        </td>
                        <td className="p-2 text-sm text-#333333">
                          {bon.type || "N/A"}
                        </td>
                        <td className="p-2 text-sm">
                          {bon.image ? (
                            <div className="flex gap-2">
                              <button
                                onClick={() => handleShowBon(bon.image)}
                                className="text-blue-600 hover:text-blue-800 flex items-center gap-1"
                              >
                                <Eye className="h-4 w-4" />
                                Voir
                              </button>
                              <button
                                onClick={() => handleDownloadBon(bon.image)}
                                className="text-green-600 hover:text-green-800 flex items-center gap-1"
                              >
                                <Download className="h-4 w-4" />
                                Télécharger
                              </button>
                            </div>
                          ) : (
                            "Aucun bon"
                          )}
                        </td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>

      {selectedSupplierInfo && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex justify-center items-center z-50 p-4">
          <div className="max-w-lg w-full bg-white rounded-xl shadow-xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="bg-gradient-to-r from-amber-50 to-amber-100 border-b relative p-6">
              <button
                onClick={closeSupplierModal}
                className="absolute right-4 top-4 rounded-full p-1.5 bg-white/90 text-zinc-500 hover:text-zinc-700 transition-colors"
              >
                <X className="h-5 w-5" />
                <span className="sr-only">Fermer</span>
              </button>
              <h2 className="text-2xl font-bold text-[#00717F]">
                Informations du Fournisseur
              </h2>
            </div>
            <div className="p-6 space-y-6">
              <div className="space-y-2">
                <h3 className="text-sm font-medium text-zinc-500">Nom</h3>
                <p className="text-lg font-medium text-zinc-900">
                  {selectedSupplierInfo.firstName} {selectedSupplierInfo.lastName}
                </p>
              </div>
              <div className="space-y-2">
                <h3 className="text-sm font-medium text-zinc-500">Téléphone</h3>
                <p className="text-lg font-medium text-zinc-900">
                  {selectedSupplierInfo.phoneNumber}
                </p>
              </div>
            </div>
            <div className="p-6 bg-zinc-50 border-t flex justify-end">
              <button
                onClick={closeSupplierModal}
                className="px-4 py-2 bg-white border border-zinc-300 rounded-lg text-zinc-700 hover:bg-zinc-50 transition-colors text-sm font-medium"
              >
                Fermer
              </button>
            </div>
          </div>
        </div>
      )}
    </Layout>
  );
}
